(()=>{"localhost"===location.hostname||location.port;const t=document.getElementById("course-container");[{title:"第一課：課程介紹+技術分析概述",link:"/course1",description:"了解技術分析的基本概念和應用。"},{title:"第二課：基本面分析概述",link:"/course2",description:"學習如何分析公司的基本面資料。"},{title:"第三課：K線圖和價格型態",link:"/course3",description:"掌握K線圖和常見價格型態的分析方法。"},{title:"第四課：簡單移動平均線（SMA）",link:"/course4",description:"探索簡單移動平均線的計算和應用。"},{title:"第五課：相對強弱指數（RSI）",link:"/course5",description:"學習如何使用RSI判斷市場超買或超賣。"},{title:"第六課：布林帶（Bollinger Bands）",link:"/course6",description:"了解布林帶的計算及其在交易中的應用。"},{title:"第七課：MACD",link:"/course7",description:"掌握MACD指標的使用技巧。"},{title:"第八課：KD指標（Stochastic Oscillator）",link:"/course8",description:"學習KD指標的計算和市場趨勢判斷。"},{title:"第九課：乖離率（BIAS）",link:"/course9",description:"了解乖離率的意義及其在交易中的應用。"}].forEach((i=>{const e=document.createElement("div");e.className="card shadow mb-4 w-75",e.innerHTML=`\n        <div class="card-header py-3 d-flex justify-content-center align-items-center">\n            <h6 class="m-0 font-weight-bold text-primary w-100" style="text-align: center;">${i.title}</h6>\n            <a href="${i.link}" class="">\n                <div class="col-auto btn btn-info">\n                    <i class="fas fa-arrow-right"></i>\n                </div>\n            </a>\n        </div>\n        <div class="card-body" style="text-align: center;">\n            ${i.description}\n        </div>\n    `,t.appendChild(e)}))})();
